CREATE OR REPLACE FUNCTION public.convert_approved_missing_listing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  req public.seller_listing_requests;
  variant uuid;
  new_ask uuid;
  path text;
  idx integer := 0;
BEGIN
  IF NEW.status IN ('rejected', 'merged_duplicate') AND OLD.status <> NEW.status THEN
    UPDATE public.seller_listing_requests
       SET status = 'rejected', updated_at = now()
     WHERE suggestion_id = NEW.id AND status = 'pending';
    RETURN NEW;
  END IF;
  IF NEW.status <> 'approved' OR NEW.created_product_id IS NULL
     OR OLD.status = 'approved' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO req FROM public.seller_listing_requests
   WHERE suggestion_id = NEW.id AND status = 'pending' FOR UPDATE;
  IF req.id IS NULL THEN RETURN NEW; END IF;

  SELECT id INTO variant FROM public.product_variants
   WHERE product_id = NEW.created_product_id AND active
   ORDER BY position, created_at LIMIT 1;
  IF variant IS NULL THEN RAISE EXCEPTION 'The new product needs an active variation'; END IF;

  INSERT INTO public.asks (
    product_id, variant_id, seller_id, price_cents, currency, item_condition,
    in_hand, seller_note, status, is_demo, parcel_length_in, parcel_width_in,
    parcel_height_in, parcel_weight_lb
  ) VALUES (
    NEW.created_product_id, variant, req.seller_id, req.price_cents, req.currency,
    req.item_condition, true, req.seller_note, 'active', false,
    req.parcel_length_in, req.parcel_width_in, req.parcel_height_in, req.parcel_weight_lb
  ) RETURNING id INTO new_ask;

  idx := 0;
  FOREACH path IN ARRAY req.evidence_paths LOOP
    INSERT INTO public.ask_media (ask_id, storage_path, position)
    VALUES (new_ask, path, idx);
    idx := idx + 1;
  END LOOP;
  idx := 0;
  FOREACH path IN ARRAY req.public_media_paths LOOP
    INSERT INTO public.listing_media (ask_id, storage_path, position, rights_attested_at)
    VALUES (new_ask, path, idx, now());
    idx := idx + 1;
  END LOOP;

  UPDATE public.seller_listing_requests
     SET status = 'converted', converted_ask_id = new_ask, updated_at = now()
   WHERE id = req.id;
  INSERT INTO public.ask_events (ask_id, actor_id, event_type, to_status, price_cents, note)
  VALUES (new_ask, NEW.reviewer_id, 'created', 'active', req.price_cents,
    'Created from an approved missing-product request; awaiting exact-item review');
  PERFORM public.notify_member(req.seller_id, 'missing_product_approved',
    'Your requested product was added',
    'Your exact-item listing is now waiting for ParkVault photo and condition approval.', NULL);
  RETURN NEW;
END;
$function$

